/**
 * The audio library — the pure half shared by tools/audio-pipeline/ (which
 * builds it) and the module (which plays from it). design/audio-system.md §2-3.
 *
 * Three stores meet here, each with one owner:
 *   data/audio/library.json          GENERATED by the pipeline: what each file
 *                                    physically is and how it was processed.
 *   data/audio/review.json           HUMAN decisions: confirm/reject, kind,
 *                                    title, category, tags, markers.
 *   data/campaign/asset-registry.json  RESERVATIONS: this track belongs to that
 *                                    villain/scene/location and nothing else.
 * `buildLibraryIndex` is the one place they are combined, so every consumer —
 * the pipeline's report, the Sound Desk, the playlist builder — sees the same
 * effective answer.
 *
 * No Foundry, no filesystem, no ffmpeg.
 */

/** Where processed audio lives, relative to Foundry's user-data root (and to audio/library/ locally). */
export const AUDIO_ROOT = "blank-inheritance-audio";

/** The ceiling every processed file's true peak is kept under, checked after encoding. */
export const TRUE_PEAK_CEILING_DBTP = -1;

/**
 * What the ENCODE aims for, a dB under the ceiling above.
 *
 * A lossy codec does not reproduce peaks exactly: measured after a first full
 * pass (2026-09-17), nine processed files came back hotter than their sources,
 * up to +1.9 dB, because Opus reconstructs a waveform rather than copying it.
 * Aiming a dB low absorbs that overshoot instead of discovering it afterwards.
 */
export const ENCODE_CEILING_DBTP = -2;

/**
 * What kinds of sound exist, and what each one means everywhere downstream.
 *
 * - `context`   which of Foundry's three AudioContexts it plays in. Diegetic
 *               sound (the world making noise) is `environment`; score is
 *               `music`; the console's own clicks are `interface`. That split
 *               is also what a player's three personal volume settings mean.
 * - `measure`   how its loudness is judged. Long beds use EBU R128 integrated
 *               loudness; short hits use their loudest 3 seconds, because an
 *               integrated reading of a two-second explosion is mostly silence.
 * - `targetLufs` the level the pipeline normalises it to. The gaps between
 *               kinds ARE the default mix: with every bus at 0 dB, ambience
 *               sits 6 dB under music, and a sting punches through both.
 * - `fireOnce`  whether it belongs on the cart wall (press, it plays, it ends)
 *               rather than on a bed that runs until stopped.
 */
export const AUDIO_KINDS = Object.freeze({
  music: Object.freeze({ context: "music", measure: "integrated", targetLufs: -18, fireOnce: false, loopByDefault: false }),
  ambience: Object.freeze({ context: "environment", measure: "integrated", targetLufs: -24, fireOnce: false, loopByDefault: true }),
  sting: Object.freeze({ context: "music", measure: "short-term", targetLufs: -14, fireOnce: true, loopByDefault: false }),
  sfx: Object.freeze({ context: "environment", measure: "short-term", targetLufs: -16, fireOnce: true, loopByDefault: false }),
  voice: Object.freeze({ context: "environment", measure: "short-term", targetLufs: -18, fireOnce: true, loopByDefault: false }),
  interface: Object.freeze({ context: "interface", measure: "short-term", targetLufs: -20, fireOnce: true, loopByDefault: false })
});

export const KIND_NAMES = Object.freeze(Object.keys(AUDIO_KINDS));

/** Review states. Only `confirmed` assets are built into Foundry playlists; `rejected` never ships. */
export const REVIEW_STATUSES = Object.freeze(["proposed", "confirmed", "rejected"]);

const SHORT_TERM_WINDOW_SEC = 3;

/** EBU R128 gates everything below -70 LUFS; ffmpeg prints -70 for "nothing measurable". */
const LOUDNESS_FLOOR = -70;

const finiteAbove = (n, floor) => (Number.isFinite(n) && n > floor ? n : null);

/**
 * The single loudness number a file is normalised by, and which measurement
 * it came from. Falls back gracefully: a bed too quiet to integrate uses its
 * loudest short-term window; a clip shorter than the 3-second short-term
 * window uses its loudest momentary (400ms) reading instead.
 */
export function measuredLoudness(kind, analysis, durationSec) {
  const def = AUDIO_KINDS[kind];
  if (!def) throw new Error(`Unknown audio kind "${kind}"`);
  const a = analysis ?? {};
  const integrated = finiteAbove(a.integratedLufs, LOUDNESS_FLOOR);
  const shortTerm = finiteAbove(a.maxShortTermLufs, LOUDNESS_FLOOR);
  const momentary = finiteAbove(a.maxMomentaryLufs, LOUDNESS_FLOOR);
  const longEnoughForShortTerm = Number(durationSec) >= SHORT_TERM_WINDOW_SEC + 0.2;

  const order =
    def.measure === "integrated"
      ? [["integrated", integrated], ["short-term", longEnoughForShortTerm ? shortTerm : null], ["momentary", momentary]]
      : [["short-term", longEnoughForShortTerm ? shortTerm : null], ["momentary", momentary], ["integrated", integrated]];
  for (const [basis, value] of order) {
    if (value !== null) return { value, basis };
  }
  return { value: null, basis: null };
}

/**
 * How much gain a file needs to land on its kind's target, and whether that
 * gain would push its true peak over the ceiling.
 *
 * When it would, there are two honest options and this picks by size: up to
 * `maxLimitingDb` of overshoot is caught by a transparent limiter (so the file
 * still lands on target); beyond that the gain is capped instead, and the
 * shortfall is reported rather than squashed — a quiet, dynamic orchestral
 * track should stay dynamic and simply play a little under its neighbours.
 */
export function planGain({ kind, analysis, durationSec, maxLimitingDb = 4, ceilingDbtp = ENCODE_CEILING_DBTP }) {
  const def = AUDIO_KINDS[kind];
  if (!def) throw new Error(`Unknown audio kind "${kind}"`);
  const { value, basis } = measuredLoudness(kind, analysis, durationSec);
  if (value === null) {
    return { targetLufs: def.targetLufs, measuredLufs: null, basis: null, gainDb: 0, limitDb: null, shortfallDb: null, silent: true };
  }
  const round1 = (n) => Math.round(n * 10) / 10;
  let gainDb = def.targetLufs - value;
  const peak = Number.isFinite(analysis?.truePeakDbtp) ? analysis.truePeakDbtp : null;
  let limitDb = null;
  let shortfallDb = 0;
  if (peak !== null && peak + gainDb > ceilingDbtp) {
    const overshoot = peak + gainDb - ceilingDbtp;
    if (overshoot <= maxLimitingDb) {
      limitDb = ceilingDbtp;
    } else {
      const capped = ceilingDbtp - peak + maxLimitingDb;
      shortfallDb = gainDb - capped;
      gainDb = capped;
      limitDb = ceilingDbtp;
    }
  }
  return {
    targetLufs: def.targetLufs,
    measuredLufs: round1(value),
    basis,
    gainDb: round1(gainDb),
    limitDb,
    shortfallDb: round1(shortfallDb),
    silent: false
  };
}

/* -------------------------------------------- */
/*  Identity                                    */
/* -------------------------------------------- */

/**
 * Commercial sound-library filenames carry a catalogue code after the name —
 * `Cicadas_BW.174`, `PoliceDispatch_S08ER.378`, `FactoryBodyShop_S011IN.249`.
 * The letters are the vendor's series code and mean nothing to a GM; the
 * number is what tells two dispatch calls apart. Keep the number, drop the code.
 */
const VENDOR_CODE = /_(?:[A-Z]{1,6}\d{0,3}[A-Z]{0,5})\.(\d+)$/;

/** A lowercase, hyphenated, filesystem- and URL-safe slug. CamelCase words are split first. */
export function slugify(text, maxLength = 64) {
  const spaced = String(text ?? "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2");
  const slug = spaced
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (slug.length <= maxLength) return slug;
  return slug.slice(0, maxLength).replace(/-+[^-]*$/, "") || slug.slice(0, maxLength);
}

/** The id stem a source filename (without extension) turns into. */
export function stemToIdBase(stem) {
  const raw = String(stem ?? "");
  const vendor = raw.match(VENDOR_CODE);
  const cleaned = vendor ? `${raw.slice(0, vendor.index)} ${vendor[1]}` : raw;
  return slugify(cleaned) || "untitled";
}

/**
 * A unique id for a new asset. `taken` is every id already in use; a clash
 * gets a numeric suffix rather than silently sharing an id, because two
 * assets under one id would make a reservation ambiguous.
 */
export function uniqueAssetId(stem, taken) {
  const base = stemToIdBase(stem);
  const used = taken instanceof Set ? taken : new Set(taken ?? []);
  if (!used.has(base)) return base;
  for (let i = 2; ; i++) {
    const candidate = `${base}-${i}`;
    if (!used.has(candidate)) return candidate;
  }
}

/** The URL path a client fetches an asset from, relative to Foundry's data root. */
export function webPathFor(asset, root = AUDIO_ROOT) {
  const rel = asset?.encode?.path;
  if (!rel) return null;
  return `${root}/${String(rel).replace(/^\/+/, "")}`;
}

/* -------------------------------------------- */
/*  Combining the three stores                  */
/* -------------------------------------------- */

const REVIEWABLE_FIELDS = ["kind", "title", "category", "tags", "loop", "markers", "note"];

/**
 * One asset as everything downstream should see it: the generated entry with
 * the human's review decisions laid over the pipeline's proposal. A review
 * field that is present always wins, even when it agrees with the proposal —
 * a confirmed decision must not flip if the classifier later changes its mind.
 */
export function effectiveAsset(entry, decision) {
  const proposal = entry?.proposal ?? {};
  const d = decision && typeof decision === "object" ? decision : {};
  const out = {
    id: entry.id,
    kind: proposal.kind,
    title: proposal.title ?? entry.id,
    category: proposal.category ?? null,
    tags: Array.isArray(proposal.tags) ? [...proposal.tags] : [],
    loop: proposal.loop === true,
    markers: [],
    note: null,
    status: REVIEW_STATUSES.includes(d.status) ? d.status : "proposed",
    source: entry.source ?? null,
    analysis: entry.analysis ?? null,
    encode: entry.encode ?? null,
    output: entry.output ?? null,
    durationSec: entry.output?.durationSec ?? entry.source?.durationSec ?? null
  };
  for (const field of REVIEWABLE_FIELDS) {
    if (d[field] === undefined) continue;
    if (field === "kind" && !AUDIO_KINDS[d.kind]) continue;
    out[field] = field === "tags" || field === "markers" ? [...(d[field] ?? [])] : d[field];
  }
  out.markers = normaliseMarkers(out.markers, out.durationSec);
  return out;
}

/**
 * Markers are named moments inside a track ("the brass comes in", 72.35s).
 * Sorted by time, ids unique, anything outside the track's own length dropped
 * — a marker past the end would schedule an event that can never fire.
 */
export function normaliseMarkers(markers, durationSec) {
  const seen = new Set();
  const limit = Number.isFinite(durationSec) ? durationSec : Infinity;
  return (Array.isArray(markers) ? markers : [])
    .filter((m) => m && typeof m.id === "string" && /^[a-z0-9-]+$/.test(m.id) && Number.isFinite(Number(m.at)))
    .map((m) => ({ id: m.id, at: Math.round(Number(m.at) * 1000) / 1000, label: typeof m.label === "string" ? m.label : m.id }))
    .filter((m) => m.at >= 0 && m.at <= limit)
    .filter((m) => (seen.has(m.id) ? false : (seen.add(m.id), true)))
    .sort((a, b) => a.at - b.at);
}

/**
 * Reservations for audio, read out of the shared asset registry. An entry
 * counts when it is `kind: "audio"` and names an asset id (its `id` field is
 * the library id, same convention as artwork: the registry id is the asset).
 */
export function audioReservations(registry) {
  const out = new Map();
  for (const entry of registry?.assets ?? []) {
    if (entry?.kind !== "audio" || typeof entry.id !== "string") continue;
    const list = out.get(entry.id) ?? [];
    list.push({ kind: entry.assignedTo?.kind ?? null, ref: entry.assignedTo?.ref ?? null, note: entry.note ?? null });
    out.set(entry.id, list);
  }
  return out;
}

/**
 * The combined view of the whole library.
 *
 * - `assets`     Map id -> effective asset (rejected assets are kept here so a
 *                report can show them, but excluded from everything playable).
 * - `pools`      music category -> ids, shuffle material. RESERVED TRACKS ARE
 *                NEVER IN A POOL: a villain's theme heard at random in a
 *                shopping scene is no longer that villain's theme.
 * - `reserved`   id -> the assignments holding it.
 * - `problems`   things a human must fix: an asset reserved for two different
 *                purposes, a reservation naming an id that doesn't exist.
 */
export function buildLibraryIndex({ library, review, registry } = {}) {
  const decisions = review?.decisions ?? {};
  const reservations = audioReservations(registry);
  const assets = new Map();
  for (const entry of library?.assets ?? []) {
    if (!entry?.id) continue;
    const asset = effectiveAsset(entry, decisions[entry.id]);
    asset.reservedFor = reservations.get(entry.id) ?? [];
    assets.set(entry.id, asset);
  }

  const problems = [];
  for (const [id, holders] of reservations) {
    if (!assets.has(id)) problems.push({ kind: "missing-asset", id, message: `The asset registry reserves "${id}", which is not in the audio library.` });
    const distinct = new Set(holders.map((h) => `${h.kind}:${h.ref}`));
    if (distinct.size > 1) {
      problems.push({
        kind: "double-reservation",
        id,
        message: `"${id}" is reserved for ${[...distinct].join(" and ")} — one track, one purpose.`
      });
    }
  }

  const playable = [...assets.values()].filter((a) => a.status !== "rejected" && a.encode?.path);
  const pools = {};
  for (const asset of playable) {
    if (asset.kind !== "music" || asset.reservedFor.length || !asset.category) continue;
    (pools[asset.category] ??= []).push(asset.id);
  }
  for (const ids of Object.values(pools)) ids.sort();

  const byKind = {};
  for (const kind of KIND_NAMES) byKind[kind] = playable.filter((a) => a.kind === kind).map((a) => a.id).sort();

  return { assets, pools, byKind, reserved: reservations, problems };
}

/**
 * Library search for the desk's browser: every whitespace-separated term must
 * match somewhere in the id, title, category or tags. Title hits rank above
 * tag hits so typing a track's own name puts it first.
 */
export function searchLibrary(index, query, { kinds = null, includeReserved = true, includeRejected = false, limit = 60 } = {}) {
  const terms = String(query ?? "")
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
  const results = [];
  for (const asset of index?.assets?.values?.() ?? []) {
    if (!includeRejected && asset.status === "rejected") continue;
    if (kinds && !kinds.includes(asset.kind)) continue;
    if (!includeReserved && asset.reservedFor?.length) continue;
    const title = String(asset.title ?? "").toLowerCase();
    const hay = [asset.id, title, asset.category ?? "", ...(asset.tags ?? [])].join(" ").toLowerCase();
    let score = 0;
    let all = true;
    for (const term of terms) {
      if (!hay.includes(term)) {
        all = false;
        break;
      }
      score += title.includes(term) ? 3 : asset.category?.includes(term) ? 2 : 1;
    }
    if (!all) continue;
    results.push({ asset, score });
  }
  results.sort((a, b) => b.score - a.score || String(a.asset.title).localeCompare(String(b.asset.title)));
  return results.slice(0, limit).map((r) => r.asset);
}

/** "3:07", "1:02:45" — how the desk prints a length or a playhead. */
export function formatDuration(sec) {
  // Number(null) is 0, and "0:00" would claim a length we do not know.
  if (sec === null || sec === undefined || sec === "") return "--:--";
  const n = Number(sec);
  if (!Number.isFinite(n) || n < 0) return "--:--";
  const total = Math.floor(n);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const ss = String(s).padStart(2, "0");
  return h ? `${h}:${String(m).padStart(2, "0")}:${ss}` : `${m}:${ss}`;
}
